create view IF NOT EXISTS EXCEPTION_BV(
	EXCEPTION_ID COMMENT 'Unique identifier for an exception',
	BRAND_ID COMMENT 'Brand Identifier specifies the code which represents an organization. The identifier should be in all capital letters. Sample codes are irb (Inspire Recognized Brands), bww(Buffalo Wild Wing), arbys (Arbys),  dnkn  (Dunkin), etc.',
	EXCEPTION_TYP_CD COMMENT 'This is the code that represents the Exception Type. Sample data is MM.',
	EXCEPTION_DOMAIN_TYPE COMMENT 'Types of Domain- Cust,Media etc',
	TRANSACTION_ID COMMENT 'The transaction identifier for that unique record that has the exception',
	EXCEPTION_DT COMMENT 'Tha date of the exception',
	TABLE_NAME COMMENT 'Name of database table that had the exception',
	COLUMN_NAME COMMENT 'Name of database table column that had the exception',
	COLUMN_VAL COMMENT 'database table column value that contains the exception',
	TABLE_PRIMARY_KEY COMMENT 'primary key of the table where the exception occured',
	EXCEPTION_REASON_TXT COMMENT 'Reason for the exception',
	SOURCE_SYSTEM_NAME COMMENT 'Source System Name specifies the origin of the data. For example, Salesforce Marketing App or Netsuite. Some systems will have a reference table where sources are identified by integers such as 1,2,3, etc.',
	LOAD_TYPE COMMENT 'The load stratedy. Daily vs one-time',
	LOAD_ID COMMENT 'Load Identifier specifies the Batch that inserted the record into the table.',
	LOAD_DTTM COMMENT 'Load Datetime is the date and time in UTC when the record was created. For example, 2021-08-11T15:02:24Z.',
	UPDATE_ID COMMENT 'Update Identifier specifies the batch id used for the update of the record.',
	UPDATE_DTTM COMMENT 'Update Datetime is the date and time in UTC when the record was last updated. For example, 2021-08-11T15:02:24Z.'
) as 
SELECT EXCEPTION.EXCEPTION_ID,EXCEPTION.BRAND_ID,EXCEPTION.EXCEPTION_TYP_CD,EXCEPTION.EXCEPTION_DOMAIN_TYPE,EXCEPTION.TRANSACTION_ID,EXCEPTION.EXCEPTION_DT,EXCEPTION.TABLE_NAME,EXCEPTION.COLUMN_NAME,EXCEPTION.COLUMN_VAL,EXCEPTION.TABLE_PRIMARY_KEY,EXCEPTION.EXCEPTION_REASON_TXT,EXCEPTION.SOURCE_SYSTEM_NAME,EXCEPTION.LOAD_TYPE,EXCEPTION.LOAD_ID,EXCEPTION.LOAD_DTTM,EXCEPTION.UPDATE_ID,EXCEPTION.UPDATE_DTTM
FROM IDS_DEV.CUST.EXCEPTION ;
